#!/usr/bin/env python3
"""
Test script to validate repeated code detection and cleaning logic.
Uses the three RF payloads from the debug log to verify the flow.
"""

from code_helpers import extract_hex_codes, detect_and_clean_repeated_code

# Three RF payloads from the debug log (14:46, 14:47, 14:49 learns)
PAYLOAD_1 = ""

PAYLOAD_2 = ""

PAYLOAD_3 = ""

print("=" * 80)
print("TESTING REPEATED CODE DETECTION & CLEANING")
print("=" * 80)

payloads = [
    ("Payload 1 (r001, 544 chars)", PAYLOAD_1),
    ("Payload 2 (r002, 640 chars)", PAYLOAD_2),
    ("Payload 3 (r003, 740 chars)", PAYLOAD_3),
]

for label, payload in payloads:
    print(f"\n{label}")
    print("-" * 80)
    
    # Extract and decode
    packets_found = extract_hex_codes(payload)
    print(f"Decoded codes found: {packets_found}")
    
    # Detect and clean
    final_code, was_cleaned, dominant = detect_and_clean_repeated_code(payload, packets_found, threshold=3)
    
    print(f"Dominant code: {dominant}")
    print(f"Was cleaned: {was_cleaned}")
    if was_cleaned:
        print(f"Final code length: {len(final_code)} chars (cleaned)")
        print(f"Final code: {final_code[:100]}...")
    else:
        print(f"Final code length: {len(final_code)} chars (original)")
        print(f"Final code: {final_code[:100]}...")

print("\n" + "=" * 80)
print("SUMMARY")
print("=" * 80)
print("✓ All three payloads should decode to dominant code 'E55F62' with count 5-6")
print("✓ Since count > 3, all three should be CLEANED via generate_rf_string")
print("✓ Cleaned codes will be shorter and consistent format (SYNC_HEADER + packet_data)")
print("✓ Each cleaned code will have the same structure regardless of original wrapper")
